## 14. 高频手撕代码

### 14.1 实现 `strlen` `[S]`

```c
#include <stddef.h>

size_t my_strlen(const char *s)
{
    const char *p = s;
    while (*p != '\0') {
        ++p;
    }
    return (size_t)(p - s);
}
```

标准 strlen 不接受 NULL；若面试题要求健壮接口，可另行约定 NULL 行为，但不要声称它等价于标准函数。

### 14.2 实现 `memmove` `[S]`

```c
#include <stddef.h>

void *my_memmove(void *dst, const void *src, size_t n)
{
    unsigned char *d = dst;
    const unsigned char *s = src;

    if (d == s || n == 0U) {
        return dst;
    }

    if (d < s) {
        for (size_t i = 0; i < n; ++i) {
            d[i] = s[i];
        }
    } else {
        for (size_t i = n; i > 0U; --i) {
            d[i - 1U] = s[i - 1U];
        }
    }
    return dst;
}
```

严格可移植地比较无关对象指针的关系有语言细节；工业库实现可用编译器/平台保证。面试重点是根据重叠方向选择前拷或后拷，`memcpy` 不允许重叠。

### 14.3 无溢出二分查找 `[S]`

```c
#include <stddef.h>
#include <stdbool.h>

bool binary_search(const int *a, size_t n, int target, size_t *index)
{
    size_t lo = 0U;
    size_t hi = n; /* 半开区间 [lo, hi) */

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2U;
        if (a[mid] < target) {
            lo = mid + 1U;
        } else {
            hi = mid;
        }
    }
    if (lo < n && a[lo] == target) {
        if (index != NULL) {
            *index = lo;
        }
        return true;
    }
    return false;
}
```

### 14.4 反转单链表 `[S]`

```c
struct node {
    int value;
    struct node *next;
};

struct node *list_reverse(struct node *head)
{
    struct node *previous = NULL;
    while (head != NULL) {
        struct node *next = head->next;
        head->next = previous;
        previous = head;
        head = next;
    }
    return previous;
}
```

### 14.5 位操作 `[S]`

```c
#include <stdbool.h>
#include <stdint.h>

uint32_t bit_set(uint32_t value, unsigned bit)
{
    return value | (UINT32_C(1) << bit);
}

uint32_t bit_clear(uint32_t value, unsigned bit)
{
    return value & ~(UINT32_C(1) << bit);
}

uint32_t bit_toggle(uint32_t value, unsigned bit)
{
    return value ^ (UINT32_C(1) << bit);
}

bool bit_test(uint32_t value, unsigned bit)
{
    return (value & (UINT32_C(1) << bit)) != 0U;
}
```

调用前必须保证 `bit < 32`。硬件寄存器可能具有写 1 清零、只写、保留位等特殊语义，不能对所有寄存器机械套读改写。

### 14.6 统计 32 位中 1 的个数 `[A]`

```c
#include <stdint.h>

unsigned popcount32(uint32_t value)
{
    unsigned count = 0U;
    while (value != 0U) {
        value &= value - 1U; /* 每次清除最低位的 1 */
        ++count;
    }
    return count;
}
```

### 14.7 有界字符串复制 `[S]`

```c
#include <stdbool.h>
#include <stddef.h>

bool string_copy(char *dst, size_t capacity, const char *src)
{
    if (dst == NULL || src == NULL || capacity == 0U) {
        return false;
    }

    size_t i = 0U;
    while (i + 1U < capacity && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return src[i] == '\0'; /* true 表示完整复制，false 表示截断 */
}
```

接口明确保证 NUL 终止，并通过返回值报告截断；这比误用 `strncpy` 更容易解释。

### 14.8 固定容量环形缓冲区（普通单线程） `[S]`

```c
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define QUEUE_CAPACITY 16U

struct byte_queue {
    uint8_t data[QUEUE_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
};

bool queue_push(struct byte_queue *q, uint8_t value)
{
    if (q == NULL || q->count == QUEUE_CAPACITY) {
        return false;
    }
    q->data[q->head] = value;
    q->head = (q->head + 1U) % QUEUE_CAPACITY;
    ++q->count;
    return true;
}

bool queue_pop(struct byte_queue *q, uint8_t *out)
{
    if (q == NULL || out == NULL || q->count == 0U) {
        return false;
    }
    *out = q->data[q->tail];
    q->tail = (q->tail + 1U) % QUEUE_CAPACITY;
    --q->count;
    return true;
}
```

判空/满有三种常见方案：留一个空槽、额外 count、额外 full 标志。count 方案能使用全部槽，但并发时 head/tail/count 多个共享字段更难同步。先写对单线程版，再根据 SPSC/MPSC/多核等具体模型设计并发版。

### 14.9 协议解析状态机 `[A]`

```c
enum parser_state { WAIT_MAGIC, WAIT_LENGTH, READ_PAYLOAD, WAIT_CHECKSUM };

struct parser {
    enum parser_state state;
    uint8_t payload[64];
    size_t expected;
    size_t used;
    uint8_t checksum;
};

void parser_reset(struct parser *p)
{
    p->state = WAIT_MAGIC;
    p->expected = 0U;
    p->used = 0U;
    p->checksum = 0U;
}
```

继续实现时先验证 length 不超过数组，再写 payload；遇到错误应明确是立即复位、丢到下一个 magic，还是保留错误统计。面试官更看边界和错误恢复，不只看 switch 能否写出来。

